class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # First pass: look for exact static match (wins over dynamic)
        for route, handler in self._routes:
            if route == path:
                return handler, {}

        # Second pass: look for dynamic matches
        best_match = None
        for route, handler in self._routes:
            if self._matches_dynamic(route, path):
                if best_match is None or self._count_segments(route) > self._count_segments(best_match[0]):
                    best_match = (route, handler)
        if best_match is not None:
            return best_match[1], self._capture_params(best_match[0], path)
        return None, {}

    def _count_segments(self, route):
        return len(route.split("/"))

    def _matches_dynamic(self, route, path):
        route_segments = route.split("/")
        path_segments = path.split("/")
        if len(route_segments) != len(path_segments):
            return False
        for rs, ps in zip(route_segments, path_segments):
            if rs.startswith("<") and rs.endswith(">"):
                # Dynamic segment: must not be empty
                if not ps:
                    return False
            else:
                # Static segment: must match exactly
                if rs != ps:
                    return False
        return True

    def _capture_params(self, route, path):
        route_segments = route.split("/")
        path_segments = path.split("/")
        params = {}
        for rs, ps in zip(route_segments, path_segments):
            if rs.startswith("<") and rs.endswith(">"):
                name = rs[1:-1]
                params[name] = ps
        return params

