import re


class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # First pass: look for exact static matches (first registered wins)
        for route, handler in self._routes:
            if route == path:
                return handler, {}

        # Second pass: look for dynamic matches among routes with <name> segments
        # Among dynamic matches, prefer the one with more segments (more specific)
        best = None
        best_seg_count = -1
        for route, handler in self._routes:
            if '<' not in route:
                continue
            if self._matches_dynamic(route, path):
                seg_count = self._count_segments(route)
                if seg_count > best_seg_count:
                    best = (handler, self._capture_params(route, path))
                    best_seg_count = seg_count
        if best:
            return best
        return None, {}

    def _matches_dynamic(self, route, path):
        """Check if path matches a dynamic route pattern like /jobs/<job_id>."""
        route_parts = route.split('/')
        path_parts = path.split('/')
        if len(route_parts) != len(path_parts):
            return False
        for rp, pp in zip(route_parts, path_parts):
            if rp.startswith('<') and rp.endswith('>'):
                # Dynamic segment: must not be empty
                if pp == '':
                    return False
            else:
                if rp != pp:
                    return False
        return True

    def _count_segments(self, route):
        return len(route.split('/'))

    def _capture_params(self, route, path):
        route_parts = route.split('/')
        path_parts = path.split('/')
        params = {}
        for rp, pp in zip(route_parts, path_parts):
            if rp.startswith('<') and rp.endswith('>'):
                name = rp[1:-1]
                params[name] = pp
        return params

