from collections import OrderedDict


class TTLCache:
    """Mapping with per-entry expiry.

    `clock` is a zero-argument callable returning a monotonic float, injected so
    tests can control time.
    """

    def __init__(self, ttl, clock, max_size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_size = max_size
        self._data = OrderedDict()

    def set(self, key, value):
        now = self.clock()
        if key in self._data:
            # Overwriting existing key: update in place, move to end (most recent)
            self._data[key] = (value, now)
            self._data.move_to_end(key)
        else:
            self._data[key] = (value, now)
            # Evict least recently used if over max_size
            if self.max_size is not None and self.max_size > 0:
                while len(self._data) > self.max_size:
                    self._data.popitem(last=False)
            elif self.max_size == 0:
                # max_size=0 means retain nothing: remove the entry we just added
                self._data.pop(key)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
        # Move accessed key to end (most recently used)
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

