class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # First pass: look for exact static matches (they always win)
        for route, handler in self._routes:
            if route == path:
                return handler, {}

        # Second pass: look for dynamic matches
        dynamic_match = None
        for route, handler in self._routes:
            if '<' not in route or '>' not in route:
                continue

            segments = self._parse_route(route)
            path_segments = path.split('/') if path else []

            if len(segments) != len(path_segments):
                continue

            params = {}
            match = True
            for seg, ps in zip(segments, path_segments):
                if seg.startswith('<') and seg.endswith('>'):
                    param_name = seg[1:-1]
                    # Empty segment must not satisfy a parameter
                    if not ps:
                        match = False
                        break
                    params[param_name] = ps
                else:
                    # Static segment must match exactly
                    if seg != ps:
                        match = False
                        break

            if match:
                dynamic_match = (handler, params)

        return dynamic_match if dynamic_match else (None, {})

    def _parse_route(self, route):
        """Parse a route pattern into segments.

        Returns a list of segments where each segment is either:
        - A static segment (e.g., 'jobs')
        - A parameter segment (e.g., '<job_id>')
        """
        segments = []
        i = 0
        while i < len(route):
            if route[i] == '<':
                # Find the closing >
                end = route.index('>', i)
                param_name = route[i+1:end]
                segments.append('<' + param_name + '>')
                i = end + 1
            else:
                # Collect the literal segment
                start = i
                while i < len(route) and route[i] != '<':
                    i += 1
                segments.append(route[start:i])
        return segments
